/// <summary>
/// The <c>METDallasPicklistRegSalesConfirmController</c> class is a controller class used for the MET Dallas picklist registration sales confirmation process.
/// </summary>
class METDallasPicklistRegSalesConfirmController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Constuct new controller object.
/// </summary>
/// <param name = "_wmsOrderTransRouteMap">WMS Picking route set.</param>
/// <param name = "_tasksNumber">Task numbers.</param>
///  <param name = "_exectionMode">Execution mode.</param>
/// <returns>New controller object.</returns>
public static SysOperationController construct(container _wmsOrderTransRouteSet, int _tasksNumber, SysOperationExecutionMode _exectionMode = SysOperationExecutionMode::Synchronous)
{
    METDallasPicklistRegSalesConfirmController controller = new METDallasPicklistRegSalesConfirmController();

    controller.initContract(_wmsOrderTransRouteSet, _tasksNumber);
    controller.parmLoadFromSysLastValue(false);
    controller.parmShowDialog(false);
    controller.parmExecutionMode(_exectionMode);

    return controller;
}

/// <summary>
/// Initializes data contract.
/// </summary>
/// <param name = "_wmsOrderTransRouteMap">WMS Picking route set.</param>
/// <param name = "_tasksNumber">Task numbers.</param>
public void initContract(container _wmsOrderTransRouteSet, int _tasksNumber)
{
    METDallasPicklistRegSalesConfirmContract contract;

    contract = this.getDataContractObject() as METDallasPicklistRegSalesConfirmContract;

    contract.parmWMSOrderTransRouteSet(_wmsOrderTransRouteSet);
    contract.parmParallelTasksNumber(_tasksNumber);             
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:DallasConfirmSalesOrders";
}
